{"code": "from hermes_tools import terminal

# Process each file
files = [
    "raw/youtube-links/Kh8tGD5liwo.md",
    "raw/youtube-links/NbldZVdusKo.md",
    "raw/youtube-links/krEDel3aGGw.md"
]

wiki_path = "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki"

urls = []
for f in files:
    result = terminal(f"grep -oP 'https?://(www\\.)?(youtube\\.com/watch\\?v=|youtu\\.be/)[\\w\\-?=&]+' {wiki_path}/{f}")
    if result['exit_code'] == 0 and result['output'].strip():
        for line in result['output'].strip().split('\n'):
            url = line.strip()
            if url:
                urls.append(url)
                print(f"FOUND: {url}")
    else:
        print(f"No URL in {f}")

print(f"\nTotal URLs: {len(urls)}")
for u in urls:
    print(f"  - {u}")
"}

